/* Boston Celtics DNA — garden night green, parquet floor, champion gold */
.theme-boston-celtics {
  --bg: oklch(0.232 0.038 168.6);
  --surface: oklch(0.279 0.047 167.5);
  --surface-2: oklch(0.325 0.055 166.6);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.768 0.039 166.2);
  --accent: oklch(0.506 0.142 149.2);
  --accent-fg: oklch(0.231 0.039 169.1);
  --accent-2: oklch(0.692 0.096 81.6);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-boston-celtics h1,
.theme-boston-celtics h2,
.theme-boston-celtics h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-boston-celtics { --font-ui: var(--font-display); }
.theme-boston-celtics h1, .theme-boston-celtics h2 { text-transform: uppercase; font-weight: 800; }
.theme-boston-celtics button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-boston-celtics { background-image: repeating-linear-gradient(45deg, oklch(0.3 0.05 160 / 30%) 0 34px, transparent 34px 68px), repeating-linear-gradient(-45deg, oklch(0.3 0.05 160 / 30%) 0 34px, transparent 34px 68px); background-size: 100% 320px; background-repeat: no-repeat; }
.theme-boston-celtics h2::before { content: "☘ "; color: var(--accent); }
.theme-boston-celtics h1 { color: var(--accent); }

/* depth */
.theme-boston-celtics ::selection { background: oklch(0.506 0.142 149.2); color: #ffffff; }
.theme-boston-celtics a { color: oklch(0.80 0.11 82); text-decoration-color: color-mix(in oklab, var(--accent-2) 60%, transparent); text-underline-offset: 3px; }
.theme-boston-celtics a:hover { color: #ffffff; text-decoration-color: var(--accent-2); text-decoration-thickness: 2px; }
.theme-boston-celtics thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--accent-2); background: oklch(0.205 0.035 168); border-bottom: 3px double var(--accent-2); }
.theme-boston-celtics td { border-bottom: 1px solid var(--line); }
.theme-boston-celtics tbody tr:hover { background: oklch(0.692 0.096 81.6 / 8%); }
.theme-boston-celtics input, .theme-boston-celtics select, .theme-boston-celtics textarea { background: oklch(0.20 0.035 168); border: 1px solid var(--line); caret-color: var(--accent-2); }
.theme-boston-celtics input:focus-visible, .theme-boston-celtics select:focus-visible, .theme-boston-celtics textarea:focus-visible { outline: none; border-color: var(--accent-2); box-shadow: 0 0 0 3px oklch(0.692 0.096 81.6 / 25%); }
.theme-boston-celtics kbd { font-family: var(--font-mono); background: oklch(0.20 0.035 168); color: oklch(0.85 0.09 82); border: 1px solid var(--accent-2); border-radius: var(--radius-sm); padding: 0.1em 0.45em; }
.theme-boston-celtics ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-boston-celtics ::-webkit-scrollbar-track { background: oklch(0.20 0.035 168); }
.theme-boston-celtics ::-webkit-scrollbar-thumb { background: oklch(0.45 0.11 150); border: 2px solid oklch(0.20 0.035 168); border-radius: 999px; }
.theme-boston-celtics ::-webkit-scrollbar-thumb:hover { background: var(--accent-2); }
.theme-boston-celtics .label-caps { color: var(--accent-2); font-weight: 700; }
/* physical: championship banner — cards trimmed like the 18 flags in the rafters */
.theme-boston-celtics .themed-border { border-color: color-mix(in oklab, var(--accent-2) 55%, transparent); box-shadow: inset 0 3px 0 var(--accent-2), var(--shadow-1); }
.theme-boston-celtics button:hover { box-shadow: inset 0 -3px 0 var(--accent-2), var(--shadow-1); }
.theme-boston-celtics button:active { transform: translateY(1px); }

/* alt mode: garden day — sanded parquet in daylight, banner gold intact */
.theme-boston-celtics.alt-mode {
  --bg: oklch(0.965 0.018 92);
  --surface: oklch(0.935 0.022 92);
  --surface-2: oklch(0.905 0.026 92);
  --fg: oklch(0.22 0.045 168);
  --fg-muted: oklch(0.44 0.045 168);
  --accent: oklch(0.45 0.13 150);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.55 0.11 80);
  --line: oklch(0.85 0.025 92);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: repeating-linear-gradient(45deg, oklch(0.80 0.06 85 / 18%) 0 34px, transparent 34px 68px), repeating-linear-gradient(-45deg, oklch(0.80 0.06 85 / 18%) 0 34px, transparent 34px 68px);
  background-size: 100% 320px;
  background-repeat: no-repeat;
}
.theme-boston-celtics.alt-mode a { color: oklch(0.48 0.10 80); }
.theme-boston-celtics.alt-mode a:hover { color: oklch(0.35 0.12 150); }
.theme-boston-celtics.alt-mode thead th { background: oklch(0.92 0.020 92); }
.theme-boston-celtics.alt-mode kbd { background: #ffffff; color: oklch(0.42 0.10 80); }
.theme-boston-celtics.alt-mode input, .theme-boston-celtics.alt-mode select, .theme-boston-celtics.alt-mode textarea { background: #ffffff; }
.theme-boston-celtics.alt-mode ::-webkit-scrollbar-track { background: oklch(0.92 0.020 92); }
.theme-boston-celtics.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.55 0.10 150); border-color: oklch(0.92 0.020 92); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
